effect.shader:
vec4 u_xlat0;
int u_xlati0;
vec4 u_xlat1;
vec4 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
float u_xlat6;
int u_xlati12;
float u_xlat18;
bool u_xlatb18;
void main()
{
    u_xlati0 = int(_samples) + int(0xFFFFFFFFu);
    u_xlat0.x = float(u_xlati0);
    u_xlat1 = vec4(_radius.x, _radius.x, _radius.y, _radius.y) * vec4(1.0, 0.0, 0.0, 1.0);
    u_xlat2.x = float(0.0);
    u_xlat2.y = float(0.0);
    u_xlat2.z = float(0.0);
    u_xlat2.w = float(0.0);
    u_xlat6 = float(0.0);
    for(int u_xlati_loop_1 = int(0) ; u_xlati_loop_1<int(_samples) ; u_xlati_loop_1++)
    {
        u_xlat18 = float(u_xlati_loop_1);
        u_xlat18 = u_xlat18 / u_xlat0.x;
        u_xlat18 = u_xlat18 + -0.5;
        u_xlat3.x = -abs(u_xlat18) * 2.0 + 1.0;
        u_xlat6 = u_xlat3.x * 2.0 + u_xlat6;
        u_xlat4 = u_xlat1 * vec4(u_xlat18) + acScreenNorm.xyxy;
        u_xlat5 = texture(inputImg, u_xlat4.xy);
        u_xlat4 = texture(inputImg, u_xlat4.zw);
        u_xlat5 = u_xlat5 * u_xlat5;
        u_xlat4 = u_xlat4 * u_xlat4;
        u_xlat5 = u_xlat5 * u_xlat3.xxxx + u_xlat2;
        u_xlat2 = u_xlat4 * u_xlat3.xxxx + u_xlat5;
    }
    u_xlat0 = u_xlat2 / vec4(u_xlat6);
    u_xlat0 = sqrt(u_xlat0);
    if(int(_use_inner_mask) != 0) {
        u_xlat1 = texture(inputImg, acScreenNorm.xy);
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat1 = u_xlat1 * u_xlat5;
        u_xlat1 = u_xlat3 * u_xlat4 + u_xlat1;
        u_xlat2.x = u_xlat4.x * u_xlat1.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat1.w;
        fragColor.xyz = u_xlat1.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
